import{_ as s,o as i,c as e,a2 as a}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"Runtime 语义三篇文章：公开证据包","description":"","frontmatter":{"title":"Runtime 语义三篇文章：公开证据包","date":"2026-08-27"},"headers":[],"relativePath":"zh/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md","filePath":"zh/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md","lastUpdated":1787846002000}'),d={name:"zh/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md"};function n(l,t,o,r,h,p){return i(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="runtime-语义三篇文章-公开证据包" tabindex="-1">Runtime 语义三篇文章：公开证据包 <a class="header-anchor" href="#runtime-语义三篇文章-公开证据包" aria-label="Permalink to &quot;Runtime 语义三篇文章：公开证据包&quot;">​</a></h1><p>状态：<strong>Published</strong>。本页随 2026-08-27 三篇 Runtime 语义文章公开，材料已脱敏，可下载、可检查。R1 提供 Windows 专用公开 probe 与脱敏记录；R2、R3 提供无网络依赖的公开 Reader / check。</p><p>目的不是证明“当前系统全部正确”，而是让文章里的样本、分类规则、实验结果和不可外推边界能够被读者独立检查。</p><h2 id="_1-证据包包含什么" tabindex="-1">1. 证据包包含什么 <a class="header-anchor" href="#_1-证据包包含什么" aria-label="Permalink to &quot;1. 证据包包含什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>公开材料</th><th>能回答什么</th><th>不能回答什么</th></tr></thead><tbody><tr><td>《取消了 Agent，子进程真的停了吗？》</td><td>Windows 二层 Node 进程树 probe、脱敏已记录结果、record-check</td><td>在一个 wrapper + 直接 child 合同下，某台 Windows 主机上的 <code>taskkill /T /F</code> 是否同时观察到两者退出；读者也可在自己的 Windows 主机重跑同一合同</td><td>任意深度进程树、逃逸后代、跨权限、容器、远程 worker 是否都被收拢</td></tr><tr><td>《任务在审查中，就等于证据没有串账吗？》</td><td>10 条脱敏 REPORT 关联样本、公开 Reader、check script</td><td>只使用显式 task key 时，样本如何分成 <code>linked / missing / conflict</code></td><td>故障率、REPORT 内容真实性、业务验收或当前产品质量</td></tr><tr><td>《一盏绿灯到底在说什么？》</td><td>5 条脱敏 Session 观察输入、公开 Reader、check script、投影反例矩阵</td><td>五类已披露观察语义能否被独立复现，以及哪些 UI 事实不能互相替代</td><td>所有桌面端、PWA、权限过滤器和端到端交付路径是否都已认证</td></tr></tbody></table><p>本包不公开任务正文、Agent 内容、提示词、绝对路径、用户名、真实 Session ID、凭据或用户项目文件。</p><hr><h2 id="_2-r1-windows-取消与-停止-证据" tabindex="-1">2. R1｜Windows 取消与“停止”证据 <a class="header-anchor" href="#_2-r1-windows-取消与-停止-证据" aria-label="Permalink to &quot;2. R1｜Windows 取消与“停止”证据&quot;">​</a></h2><p>这部分对应《取消了 Agent，子进程真的停了吗？》一文。</p><h3 id="实验合同" tabindex="-1">实验合同 <a class="header-anchor" href="#实验合同" aria-label="Permalink to &quot;实验合同&quot;">​</a></h3><p>在新的临时目录中，由 wrapper 启动一个长寿命直接 child。确认两个 PID 都可观察后，执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taskkill /PID &lt;wrapper&gt; /T /F</span></span></code></pre></div><p>并在三秒内分别检查 wrapper 与直接 child 是否仍可观察。</p><p>第一次受控主机记录为：</p><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>wrapper 与直接 child 在终止前可观察</td><td>是</td></tr><tr><td><code>taskkill /T /F</code> 退出码</td><td><code>0</code></td></tr><tr><td>wrapper 退出被观察</td><td>是</td></tr><tr><td>直接 child 退出被观察</td><td>是</td></tr><tr><td>结果</td><td><code>PASS</code></td></tr><tr><td><code>kernel_containment_proven</code></td><td><code>false</code></td></tr></tbody></table><p>公开材料：</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-tree-probe.mjs">2026-08-27-r1-windows-taskkill-tree-probe.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result.json">2026-08-27-r1-windows-taskkill-recorded-result.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result-check.mjs">2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</a></li></ul><p>脱敏已记录结果明确包含：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;windows_taskkill_tree_probe_only&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wrapper_exit_observed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;child_exit_observed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;termination_exit_code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kernel_containment_proven&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="两种检查不能混为一谈" tabindex="-1">两种检查不能混为一谈 <a class="header-anchor" href="#两种检查不能混为一谈" aria-label="Permalink to &quot;两种检查不能混为一谈&quot;">​</a></h3><p>检查公开记录本身：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</span></span></code></pre></div><p>预期输出：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_windows_taskkill_tree_probe_result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kernel_containment_proven&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这只验证公开记录的结构和声明边界，不重新执行操作系统实验。</p><p>要重新实验 <code>taskkill /T /F</code>，必须在 <strong>Windows</strong> 上运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-tree-probe.mjs</span></span></code></pre></div><p>probe 会创建临时 wrapper + direct child，等待两者可观察，再执行 <code>taskkill /T /F</code> 并分别检查两个 PID。非 Windows 主机直接拒绝运行，而不是给出假 PASS。</p><p>即使再次得到 PASS，它仍然只说明这个公开合同中的两个已知 PID 被观察到退出。它不证明进程树在内核意义上是一个封闭集合；child 脱离原关系、短寿命中间进程生成 grandchild、跨权限、继续派生、容器化或远程 worker 都需要新的反例实验。</p><hr><h2 id="_3-r2-report-与-task-的显式关联" tabindex="-1">3. R2｜REPORT 与 TASK 的显式关联 <a class="header-anchor" href="#_3-r2-report-与-task-的显式关联" aria-label="Permalink to &quot;3. R2｜REPORT 与 TASK 的显式关联&quot;">​</a></h2><p>脱敏 fixture：</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-report-association-fixture.json">2026-08-27-r2-report-association-fixture.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader.mjs">2026-08-27-r2-association-reader.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader-check.mjs">2026-08-27-r2-association-reader-check.mjs</a></li></ul><h3 id="分类规则" tabindex="-1">分类规则 <a class="header-anchor" href="#分类规则" aria-label="Permalink to &quot;分类规则&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>action.task_id 与 ledger.task_id 都存在且相等  → linked</span></span>
<span class="line"><span>action.task_id 缺失                              → missing</span></span>
<span class="line"><span>两者都存在但不相等                              → conflict</span></span></code></pre></div><p>禁止使用文件名相似、写入时间接近、角色、模型推断或“默认选择最新记录”来补关系。</p><h3 id="_10-条脱敏样本" tabindex="-1">10 条脱敏样本 <a class="header-anchor" href="#_10-条脱敏样本" aria-label="Permalink to &quot;10 条脱敏样本&quot;">​</a></h3><table tabindex="0"><thead><tr><th>REPORT</th><th>action task</th><th>ledger task</th><th>输出</th></tr></thead><tbody><tr><td>R01</td><td>T01</td><td>T01</td><td>linked</td></tr><tr><td>R02</td><td>T02</td><td>T04</td><td>conflict</td></tr><tr><td>R03</td><td>T02</td><td>T03</td><td>conflict</td></tr><tr><td>R04</td><td>—</td><td>T02</td><td>missing</td></tr><tr><td>R05</td><td>T01</td><td>T01</td><td>linked</td></tr><tr><td>R06</td><td>—</td><td>T04</td><td>missing</td></tr><tr><td>R07</td><td>—</td><td>T03</td><td>missing</td></tr><tr><td>R08</td><td>T01</td><td>T01</td><td>linked</td></tr><tr><td>R09</td><td>—</td><td>T09</td><td>missing</td></tr><tr><td>R10</td><td>T08</td><td>T08</td><td>linked</td></tr></tbody></table><p>汇总：<code>linked = 4</code>、<code>missing = 4</code>、<code>conflict = 2</code>。</p><p>fixture 由固定第一方历史记录脱敏派生，保留 task key 的等值、缺失和冲突关系。原始两份 JSONL 的 SHA-256 分别为：</p><ul><li><code>47dda7d8cd18b2a11241854823964d9e0a67298535de06e04f2acb807459ac11</code></li><li><code>45cd1d3b4ffc088574d08df48de3ad5db6fd5a99b288005c7a048f2a7355342b</code></li></ul><p>公开检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r2-association-reader-check.mjs</span></span></code></pre></div><p>预期输出：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_historical_association&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;counts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;linked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;missing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;conflict&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>公开 Reader 是为了让读者检查本文披露的分类规则和脱敏样本；它不是对完整 Runtime 的模拟。</p><hr><h2 id="_4-r3-ui-状态投影-五类事实不能压成一盏绿灯" tabindex="-1">4. R3｜UI 状态投影：五类事实不能压成一盏绿灯 <a class="header-anchor" href="#_4-r3-ui-状态投影-五类事实不能压成一盏绿灯" aria-label="Permalink to &quot;4. R3｜UI 状态投影：五类事实不能压成一盏绿灯&quot;">​</a></h2><p>这部分对应《一盏绿灯到底在说什么？》一文。</p><p>第一方源路径中，Session 观察器把五种输入分成五类互斥输出。源测试中的一个定向 test 包含 <strong>5 个分类断言</strong>；早先文章里的“1/1”只表示这个 test case 通过，不应被理解成“只验证了一个状态”，更不能理解成全 UI 回归。</p><h3 id="五类已披露观察合同" tabindex="-1">五类已披露观察合同 <a class="header-anchor" href="#五类已披露观察合同" aria-label="Permalink to &quot;五类已披露观察合同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入观察</th><th>输出</th><th>页面不应升级成</th></tr></thead><tbody><tr><td>Session <code>running</code> + live + 有 progress</td><td><code>executing_with_progress</code></td><td>已交付</td></tr><tr><td>Session <code>running</code> + live + 无细粒度 progress</td><td><code>executing_without_fine_progress</code></td><td>已失败</td></tr><tr><td>Session <code>running</code> + 非 live</td><td><code>session_without_live_execution</code></td><td>正在推进</td></tr><tr><td>Session <code>completed</code> + REPORT 尚未写入</td><td><code>completed_waiting_report</code></td><td>已验收</td></tr><tr><td>Session <code>failed</code> / <code>session_lost</code></td><td><code>technical_error</code></td><td>业务任务失败</td></tr></tbody></table><h3 id="公开、可重跑的脱敏复现器" tabindex="-1">公开、可重跑的脱敏复现器 <a class="header-anchor" href="#公开、可重跑的脱敏复现器" aria-label="Permalink to &quot;公开、可重跑的脱敏复现器&quot;">​</a></h3><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-fixture.json">2026-08-27-r3-ui-status-projection-fixture.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-reader.mjs">2026-08-27-r3-ui-status-projection-reader.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-check.mjs">2026-08-27-r3-ui-status-projection-check.mjs</a></li></ul><p>fixture 含 5 条脱敏输入，每条对应一种已披露分类。公开 Reader 按披露的判断顺序复现分类合同；check script 对五条记录逐条比对 <code>actual === expected</code>，并同时检查五类计数。</p><p>运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r3-ui-status-projection-check.mjs</span></span></code></pre></div><p>预期输出：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_runtime_session_observation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;assertions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这里必须区分两件事：<strong>公开 Reader 是可复核的合同复现器，不是私有生产源码；5 条公开断言验证的是已披露分类语义，不是桌面端/PWA 的端到端 UI 认证。</strong></p><h3 id="投影反例矩阵" tabindex="-1">投影反例矩阵 <a class="header-anchor" href="#投影反例矩阵" aria-label="Permalink to &quot;投影反例矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组合</th><th>合格展示</th></tr></thead><tbody><tr><td>viewer 不是 owner，但权限允许读取且存在 fresh local session</td><td>依据 canonical execution source 展示实际执行；不能仅因非 owner 隐藏</td></tr><tr><td>Gateway online，但 managed job heartbeat 已过期</td><td>同时展示连接与 job 活性；不能把 online 写成“正在执行”</td></tr><tr><td>workflow 已 <code>done</code>，evidence 仍有 conflict</td><td>保留 <code>done</code> 与 evidence conflict 两个事实，不互相覆盖</td></tr><tr><td>runtime / disk / context identity 不一致</td><td>显示 <code>projection_conflict</code> / unknown，不发布为 online</td></tr></tbody></table><p>这些组合不是为了制造更多颜色，而是检查<strong>正交性</strong>：viewer authority、连接、Session 活性、progress、REPORT 与 lifecycle 各自只回答自己的问题。</p><hr><h2 id="_5-如何独立检查" tabindex="-1">5. 如何独立检查 <a class="header-anchor" href="#_5-如何独立检查" aria-label="Permalink to &quot;5. 如何独立检查&quot;">​</a></h2><p>R1、R2、R3 的公开附件都不需要访问私有仓库。R1 的真实 probe 需要 Windows；R1 record-check、R2 与 R3 使用 Node 即可。</p><p>R1 公开记录检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</span></span></code></pre></div><p>R1 Windows 重跑：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-tree-probe.mjs</span></span></code></pre></div><p>R2：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r2-association-reader-check.mjs</span></span></code></pre></div><p>R3：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r3-ui-status-projection-check.mjs</span></span></code></pre></div><p>检查者应特别确认：</p><ol><li>R1 的 <code>PASS</code> 没有被扩写成任意进程树 containment 保证；</li><li>R1 的 public probe 与 recorded result 是两种不同证据：一个可重新实验，一个记录既有主机观察；</li><li>R2 脱敏没有改变 task key 的相等、缺失和冲突关系；</li><li>R3 的五类公开断言没有被扩写成全端 UI / PWA 回归；</li><li><code>technical_error</code> 没有被写成业务失败，<code>completed_waiting_report</code> 没有被写成正式验收；</li><li>文章没有让取消请求、命令返回码、PID 消失、Gateway、Session、progress、REPORT 或 lifecycle 中任何一层替另一层签字。</li></ol><h2 id="_6-总体证据边界" tabindex="-1">6. 总体证据边界 <a class="header-anchor" href="#_6-总体证据边界" aria-label="Permalink to &quot;6. 总体证据边界&quot;">​</a></h2><p>这个公开包是一组<strong>可审查的工程切片</strong>，不是产品认证，也不是统计学意义上的大样本评测。</p><ul><li>R1：一份既有 Windows 主机二层样本 + 一个公开同合同 probe；</li><li>R2：10 条脱敏历史关联样本；</li><li>R3：5 条语义分类输入 + 投影反例矩阵。</li></ul><p>因此，本文和相关三篇文章的结论都必须限制在对应样本、规则、版本和公开材料内。证据包的价值不在于把系统描述成“全绿”，而在于让读者能够区分：<strong>什么已经观察到，什么可以重跑，什么仍然没有被证明。</strong></p>`,80)])])}const u=s(d,[["render",n]]);export{k as __pageData,u as default};
